import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
BASE=ROOT/"problems"/"strings"
tasks=[
{"slug":"19-add-decimal-strings","title":"Add Decimal Strings","difficulty":"Medium","subtopic":"Parsing","method":"addStrings","params":[["num1","String"],["num2","String"]],"returns":"String","description":"Given two non-negative decimal integers represented as strings, return their sum as a decimal string. Neither input has leading zeroes unless it is exactly `\"0\"`. Do not convert the entire input to a built-in integer type. Input: `num1` and `num2`. Output: their exact sum as a string.","constraints":["1 <= num1.length, num2.length <= 10000","Each input contains only decimal digits","No leading zeroes unless the input is \"0\""],"time":"O(m+n)","space":"O(m+n)","py":"        i, j, carry = len(num1) - 1, len(num2) - 1, 0\n        out = []\n        while i >= 0 or j >= 0 or carry:\n            a = ord(num1[i]) - 48 if i >= 0 else 0\n            b = ord(num2[j]) - 48 if j >= 0 else 0\n            carry, digit = divmod(a + b + carry, 10)\n            out.append(str(digit))\n            i -= 1; j -= 1\n        return ''.join(reversed(out))","java":"        int i = num1.length() - 1, j = num2.length() - 1, carry = 0;\n        StringBuilder out = new StringBuilder();\n        while (i >= 0 || j >= 0 || carry > 0) {\n            int a = i >= 0 ? num1.charAt(i--) - '0' : 0;\n            int b = j >= 0 ? num2.charAt(j--) - '0' : 0;\n            int sum = a + b + carry; out.append((char)('0' + sum % 10)); carry = sum / 10;\n        }\n        return out.reverse().toString();","examples":[({"num1":"456","num2":"77"},"533"),({"num1":"0","num2":"0"},"0")],"tests":[{"num1":"1","num2":"9"},{"num1":"999","num2":"1"},{"num1":"123","num2":"456"},{"num1":"999999999999999999","num2":"1"},{"num1":"500","num2":"500"},{"num1":"8","num2":"0"},{"num1":"12345678901234567890","num2":"98765432109876543210"},{"num1":"1","num2":"1"},{"num1":"9090","num2":"910"}]},
{"slug":"20-compare-dotted-versions","title":"Compare Dotted Version Numbers","difficulty":"Medium","subtopic":"Parsing","method":"compareVersion","params":[["version1","String"],["version2","String"]],"returns":"int","description":"Compare two version strings made of non-negative decimal revision numbers separated by dots. Compare revisions from left to right, treating missing trailing revisions as zero and ignoring leading zeroes within each revision. Return -1 if the first version is smaller, 1 if it is larger, or 0 if they are equal. Input: `version1`, `version2`. Output: -1, 0, or 1.","constraints":["1 <= version1.length, version2.length <= 10000","Each revision contains at least one decimal digit","A version has at most 1000 revisions"],"time":"O(m+n)","space":"O(m+n)","py":"        a, b = version1.split('.'), version2.split('.')\n        for i in range(max(len(a), len(b))):\n            x = a[i].lstrip('0') if i < len(a) else ''\n            y = b[i].lstrip('0') if i < len(b) else ''\n            if len(x) != len(y):\n                return 1 if len(x) > len(y) else -1\n            if x != y:\n                return 1 if x > y else -1\n        return 0","java":"        String[] a = version1.split(\"\\\\.\", -1), b = version2.split(\"\\\\.\", -1);\n        for (int i = 0; i < Math.max(a.length, b.length); i++) {\n            String x = i < a.length ? a[i].replaceFirst(\"^0+\", \"\") : \"\";\n            String y = i < b.length ? b[i].replaceFirst(\"^0+\", \"\") : \"\";\n            if (x.length() != y.length()) return x.length() > y.length() ? 1 : -1;\n            int cmp = x.compareTo(y); if (cmp != 0) return cmp > 0 ? 1 : -1;\n        }\n        return 0;","examples":[({"version1":"1.01","version2":"1.001"},0),({"version1":"1.0.1","version2":"1"},1)],"tests":[{"version1":"0.1","version2":"1.1"},{"version1":"1.0","version2":"1"},{"version1":"7.5.2.4","version2":"7.5.3"},{"version1":"1.0.0.0","version2":"1"},{"version1":"999999999999999999","version2":"1000000000000000000"},{"version1":"1.00000000000000000002","version2":"1.2"},{"version1":"0.0.0","version2":"0"},{"version1":"2.10","version2":"2.9"},{"version1":"1.2.3","version2":"1.2.3.1"}]},
{"slug":"21-reverse-vowels-in-string","title":"Reverse Vowels in a String","difficulty":"Easy","subtopic":"Parsing","method":"reverseVowels","params":[["s","String"]],"returns":"String","description":"Given a string `s`, reverse only its vowels and leave every other character in its original position. Vowels are `a`, `e`, `i`, `o`, `u` in either case. Input: an ASCII string `s`. Output: the transformed string.","constraints":["1 <= s.length <= 100000","s contains only ASCII letters and spaces"],"time":"O(n)","space":"O(n)","py":"        chars = list(s)\n        vowels = set('aeiouAEIOU')\n        i, j = 0, len(chars) - 1\n        while i < j:\n            while i < j and chars[i] not in vowels: i += 1\n            while i < j and chars[j] not in vowels: j -= 1\n            chars[i], chars[j] = chars[j], chars[i]\n            i += 1; j -= 1\n        return ''.join(chars)","java":"        char[] a = s.toCharArray(); int i = 0, j = a.length - 1;\n        while (i < j) {\n            while (i < j && !isVowel(a[i])) i++;\n            while (i < j && !isVowel(a[j])) j--;\n            char t = a[i]; a[i++] = a[j]; a[j--] = t;\n        }\n        return new String(a);\n    }\n    private boolean isVowel(char c) { return \"aeiouAEIOU\".indexOf(c) >= 0;","examples":[({"s":"hello"},"holle"),({"s":"aA"},"Aa")],"tests":[{"s":"leetcode"},{"s":"rhythm"},{"s":"a"},{"s":".,!?"},{"s":"Design a string"},{"s":"AEIOU"},{"s":"u, a"},{"s":"bcdEfG"},{"s":"AaEeIiOoUu"}]},
{"slug":"22-detect-capital-usage","title":"Detect Capital Usage","difficulty":"Easy","subtopic":"Parsing","method":"detectCapitalUse","params":[["word","String"]],"returns":"boolean","description":"A word uses capital letters correctly if all its letters are uppercase, all are lowercase, or only its first letter is uppercase. Given an English word, return whether its capitalization follows one of these rules. Input: a non-empty ASCII English word `word`. Output: true when capitalization is valid.","constraints":["1 <= word.length <= 100","word contains only English letters A-Z and a-z"],"time":"O(n)","space":"O(1)","py":"        return word.isupper() or word.islower() or (word[0].isupper() and word[1:].islower())","java":"        boolean allUpper = true, allLower = true;\n        for (int i = 0; i < word.length(); i++) { char c = word.charAt(i); if (Character.isLowerCase(c)) allUpper = false; else allLower = false; }\n        boolean title = Character.isUpperCase(word.charAt(0));\n        for (int i = 1; i < word.length(); i++) if (!Character.isLowerCase(word.charAt(i))) title = false;\n        return allUpper || allLower || title;","examples":[({"word":"USA"},True),({"word":"FlaG"},False)],"tests":[{"word":"Google"},{"word":"leetcode"},{"word":"A"},{"word":"z"},{"word":"mL"},{"word":"aBC"},{"word":"Aa"},{"word":"ABc"},{"word":"Coding"}]},
{"slug":"23-buddy-strings","title":"Buddy Strings","difficulty":"Easy","subtopic":"Anagrams","method":"buddyStrings","params":[["s","String"],["goal","String"]],"returns":"boolean","description":"Two strings are buddy strings if swapping exactly two distinct positions in `s` makes it equal to `goal`. If the strings already match, the swap must exchange two equal characters. Return whether `s` and `goal` are buddy strings. Input: lowercase strings `s` and `goal`. Output: true or false.","constraints":["0 <= s.length, goal.length <= 10000","s and goal contain only lowercase English letters"],"time":"O(n)","space":"O(1)","py":"        if len(s) != len(goal): return False\n        diff = [i for i in range(len(s)) if s[i] != goal[i]]\n        if not diff:\n            return len(set(s)) < len(s)\n        return len(diff) == 2 and s[diff[0]] == goal[diff[1]] and s[diff[1]] == goal[diff[0]]","java":"        if (s.length() != goal.length()) return false;\n        int first = -1, second = -1, mismatches = 0; boolean[] seen = new boolean[26]; boolean duplicate = false;\n        for (int i = 0; i < s.length(); i++) { int c = s.charAt(i) - 'a'; if (seen[c]) duplicate = true; seen[c] = true; if (s.charAt(i) != goal.charAt(i)) { if (mismatches == 0) first = i; else if (mismatches == 1) second = i; mismatches++; } }\n        if (mismatches == 0) return duplicate;\n        return mismatches == 2 && s.charAt(first) == goal.charAt(second) && s.charAt(second) == goal.charAt(first);","examples":[({"s":"ab","goal":"ba"},True),({"s":"ab","goal":"ab"},False)],"tests":[{"s":"aa","goal":"aa"},{"s":"aaaaaaabc","goal":"aaaaaaacb"},{"s":"abc","goal":"acb"},{"s":"abc","goal":"abc"},{"s":"","goal":""},{"s":"ab","goal":"ca"},{"s":"aab","goal":"aba"},{"s":"abcd","goal":"badc"},{"s":"abc","goal":"ab"}]},
{"slug":"24-kmp-substring-search","title":"KMP Substring Search","difficulty":"Medium","subtopic":"String Matching","method":"strStr","params":[["haystack","String"],["needle","String"]],"returns":"int","description":"Given strings `haystack` and `needle`, return the index of the first occurrence of `needle` in `haystack`, or -1 if it does not occur. The empty needle occurs at index 0. Input: two strings. Output: the first matching index or -1.","constraints":["0 <= haystack.length, needle.length <= 100000","Both strings contain lowercase English letters"],"time":"O(n+m)","space":"O(m)","py":"        if not needle: return 0\n        lps = [0] * len(needle)\n        j = 0\n        for i in range(1, len(needle)):\n            while j and needle[i] != needle[j]: j = lps[j - 1]\n            if needle[i] == needle[j]: j += 1; lps[i] = j\n        j = 0\n        for i, c in enumerate(haystack):\n            while j and c != needle[j]: j = lps[j - 1]\n            if c == needle[j]: j += 1\n            if j == len(needle): return i - j + 1\n        return -1","java":"        if (needle.isEmpty()) return 0;\n        int[] lps = new int[needle.length()]; int j = 0;\n        for (int i = 1; i < needle.length(); i++) { while (j > 0 && needle.charAt(i) != needle.charAt(j)) j = lps[j - 1]; if (needle.charAt(i) == needle.charAt(j)) lps[i] = ++j; }\n        j = 0;\n        for (int i = 0; i < haystack.length(); i++) {\n            while (j > 0 && haystack.charAt(i) != needle.charAt(j)) j = lps[j - 1];\n            if (haystack.charAt(i) == needle.charAt(j)) j++;\n            if (j == needle.length()) return i - j + 1;\n        }\n        return -1;","examples":[({"haystack":"sadbutsad","needle":"sad"},0),({"haystack":"leetcode","needle":"leeto"},-1)],"tests":[{"haystack":"aaaaa","needle":"bba"},{"haystack":"abc","needle":""},{"haystack":"mississippi","needle":"issip"},{"haystack":"ababababca","needle":"abababca"},{"haystack":"a","needle":"a"},{"haystack":"","needle":"a"},{"haystack":"abcabcabcd","needle":"abcabcd"},{"haystack":"aaaaaaab","needle":"aaaab"},{"haystack":"xyz","needle":"xyzq"}]},
{"slug":"25-count-binary-substrings","title":"Count Binary Substrings","difficulty":"Medium","subtopic":"Substrings","method":"countBinarySubstrings","params":[["s","String"]],"returns":"int","description":"A substring is balanced when it contains the same positive number of consecutive `0` characters followed by consecutive `1` characters, or the same number of consecutive `1` characters followed by `0` characters. Given a non-empty binary string, return the number of balanced substrings. Input: `s` containing only 0 and 1. Output: the count.","constraints":["1 <= s.length <= 100000","s contains only '0' and '1'"],"time":"O(n)","space":"O(1)","py":"        previous = 0\n        run = 1\n        total = 0\n        for i in range(1, len(s)):\n            if s[i] == s[i - 1]: run += 1\n            else: total += min(previous, run); previous, run = run, 1\n        return total + min(previous, run)","java":"        int previous = 0, run = 1, total = 0;\n        for (int i = 1; i < s.length(); i++) { if (s.charAt(i) == s.charAt(i - 1)) run++; else { total += Math.min(previous, run); previous = run; run = 1; } }\n        return total + Math.min(previous, run);","examples":[({"s":"00110011"},6),({"s":"10101"},4)],"tests":[{"s":"0"},{"s":"1"},{"s":"000111"},{"s":"1110000"},{"s":"00110"},{"s":"01010101"},{"s":"0000"},{"s":"11001100"},{"s":"000111000"}]},
{"slug":"26-valid-word-abbreviation","title":"Valid Word Abbreviation","difficulty":"Easy","subtopic":"Parsing","method":"validWordAbbreviation","params":[["word","String"],["abbr","String"]],"returns":"boolean","description":"An abbreviation matches a word when each letter matches literally and each positive decimal number skips exactly that many characters. A number cannot start with zero. Given lowercase `word` and an abbreviation containing lowercase letters and digits, return whether it matches the whole word. Input: `word`, `abbr`. Output: true or false.","constraints":["1 <= word.length <= 10000","1 <= abbr.length <= 10000","word contains lowercase letters; abbr contains lowercase letters and digits"],"time":"O(n+m)","space":"O(1)","py":"        i = j = 0\n        while j < len(abbr):\n            if abbr[j].isdigit():\n                if abbr[j] == '0': return False\n                skip = 0\n                while j < len(abbr) and abbr[j].isdigit():\n                    skip = skip * 10 + int(abbr[j]); j += 1\n                i += skip\n                if i > len(word): return False\n            else:\n                if i >= len(word) or word[i] != abbr[j]: return False\n                i += 1; j += 1\n        return i == len(word)","java":"        int i = 0, j = 0;\n        while (j < abbr.length()) {\n            char c = abbr.charAt(j);\n            if (Character.isDigit(c)) {\n                if (c == '0') return false; long skip = 0;\n                while (j < abbr.length() && Character.isDigit(abbr.charAt(j))) { skip = skip * 10 + abbr.charAt(j++) - '0'; if (skip > word.length()) return false; }\n                i += (int) skip; if (i > word.length()) return false;\n            } else { if (i >= word.length() || word.charAt(i) != c) return false; i++; j++; }\n        }\n        return i == word.length();","examples":[({"word":"internationalization","abbr":"i12iz4n"},True),({"word":"apple","abbr":"a2e"},False)],"tests":[{"word":"substitution","abbr":"s10n"},{"word":"substitution","abbr":"s010n"},{"word":"abbreviation","abbr":"a01n"},{"word":"hi","abbr":"2i"},{"word":"word","abbr":"4"},{"word":"word","abbr":"5"},{"word":"a","abbr":"1"},{"word":"a","abbr":"a"},{"word":"ab","abbr":"a1"}]},
{"slug":"27-minimum-removals-for-valid-parentheses","title":"Minimum Removals for Valid Parentheses","difficulty":"Medium","subtopic":"Parsing","method":"minRemoveToMakeValid","params":[["s","String"]],"returns":"String","description":"Given a string containing lowercase letters and parentheses, remove the fewest parentheses so the remaining parentheses are balanced. When scanning left to right, discard a closing parenthesis that has no unmatched opening parenthesis. If openings remain at the end, discard the rightmost such openings. Preserve all other characters. Input: `s`. Output: the resulting string.","constraints":["1 <= s.length <= 100000","s contains lowercase English letters and '(' or ')'"],"time":"O(n)","space":"O(n)","py":"        kept = []\n        open_count = 0\n        for c in s:\n            if c == '(': open_count += 1; kept.append(c)\n            elif c == ')':\n                if open_count == 0: continue\n                open_count -= 1; kept.append(c)\n            else: kept.append(c)\n        out = []\n        for c in reversed(kept):\n            if c == '(' and open_count: open_count -= 1\n            else: out.append(c)\n        return ''.join(reversed(out))","java":"        StringBuilder kept = new StringBuilder(); int open = 0;\n        for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c == '(') { open++; kept.append(c); } else if (c == ')') { if (open == 0) continue; open--; kept.append(c); } else kept.append(c); }\n        StringBuilder out = new StringBuilder();\n        for (int i = kept.length() - 1; i >= 0; i--) { char c = kept.charAt(i); if (c == '(' && open > 0) open--; else out.append(c); }\n        return out.reverse().toString();","examples":[({"s":"lee(t(c)o)de)"},"lee(t(c)o)de"),({"s":"a)b(c)d"},"ab(c)d")],"tests":[{"s":"))("},{"s":"(a(b(c)d)"},{"s":"abc"},{"s":"((a))"},{"s":"a((b)c))"},{"s":"(()"},{"s":"())()(("},{"s":"x(y)z"},{"s":"(((("}]},
{"slug":"28-shortest-palindrome-by-prepending","title":"Shortest Palindrome by Prepending","difficulty":"Hard","subtopic":"Palindromes","method":"shortestPalindrome","params":[["s","String"]],"returns":"String","description":"Given a string `s`, add the fewest characters possible to its front so that the entire result is a palindrome. Added characters must come from `s` in reverse order; characters already in `s` cannot be rearranged. Input: lowercase string `s`. Output: the shortest resulting palindrome.","constraints":["0 <= s.length <= 100000","s contains lowercase English letters"],"time":"O(n)","space":"O(n)","py":"        rev = s[::-1]\n        seq = s + '#' + rev\n        lps = [0] * len(seq)\n        for i in range(1, len(seq)):\n            j = lps[i - 1]\n            while j and seq[i] != seq[j]: j = lps[j - 1]\n            if seq[i] == seq[j]: j += 1\n            lps[i] = j\n        k = lps[-1]\n        return rev[:len(s) - k] + s","java":"        String rev = new StringBuilder(s).reverse().toString(); String seq = s + \"#\" + rev; int[] lps = new int[seq.length()];\n        for (int i = 1; i < seq.length(); i++) { int j = lps[i - 1]; while (j > 0 && seq.charAt(i) != seq.charAt(j)) j = lps[j - 1]; if (seq.charAt(i) == seq.charAt(j)) j++; lps[i] = j; }\n        int k = lps[seq.length() - 1]; return rev.substring(0, s.length() - k) + s;","examples":[({"s":"aacecaaa"},"aaacecaaa"),({"s":"abcd"},"dcbabcd")],"tests":[{"s":"a"},{"s":"aa"},{"s":"aba"},{"s":"abb"},{"s":""},{"s":"abcdc"},{"s":"abbacd"},{"s":"aaaa"},{"s":"race"}]}
]

def py_type(t): return {"int":"int","boolean":"bool","String":"str"}[t]
def java_type(t): return t
roster_path=ROOT/"problems"/"roster.json"; roster=json.loads(roster_path.read_text())
for p in tasks:
    folder=BASE/p["slug"]; folder.mkdir()
    params=[{"name":n,"type":t} for n,t in p["params"]]
    meta={"title":p["title"],"difficulty":p["difficulty"],"subtopic":p["subtopic"],"companies":["Amazon","Google","Microsoft"],"description":p["description"],"constraints":p["constraints"],"hints":["Keep track of the smallest state needed to continue matching or comparing characters.","Test empty, one-character, repeated-character, and boundary inputs."],"examples":[{"input":", ".join(f"{k} = {json.dumps(v)}" for k,v in x.items()),"output":json.dumps(y,separators=(",",":"))} for x,y in p["examples"]],"timeComplexity":p["time"],"spaceComplexity":p["space"],"compare":"exact","signature":{"kind":"function","method":p["method"],"params":params,"returns":p["returns"]}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    pyparams="".join(f", {n}: {py_type(t)}" for n,t in p["params"])
    (folder/"solution.py").write_text(f"class Solution:\n    def {p['method']}(self{pyparams}) -> {py_type(p['returns'])}:\n"+p["py"]+"\n")
    jparams=", ".join(f"{java_type(t)} {n}" for n,t in p["params"])
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {java_type(p['returns'])} {p['method']}({jparams}) {{\n"+p["java"]+"\n    }\n}\n")
    cases=[x for x,_ in p["examples"]]+p["tests"]
    if len(cases)<11: raise ValueError((p["slug"],len(cases)))
    visible,hidden=cases[:3],cases[3:]
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":x} for x in visible])+"\n\ndef hidden():\n    return "+repr([{"in":x} for x in hidden])+"\n")
    roster.setdefault("strings",[]).append([p["slug"],p["title"],p["difficulty"],p["subtopic"],None])
roster_path.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} string questions")
